import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportExportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String customTitle = req.getParameter("title");

        // Validate report ID is numeric
        if (reportId == null || !reportId.matches("\\d+")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Format whitelist
        if (format == null || !format.matches("(pdf|csv|xlsx)")) {
            format = "pdf";
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Get report metadata
            String metaQuery = "SELECT name, owner_id, department FROM reports WHERE id = " + reportId;
            Statement metaStmt = conn.createStatement();
            ResultSet metaRs = metaStmt.executeQuery(metaQuery);

            if (!metaRs.next()) {
                resp.sendError(404, "Report not found");
                return;
            }

            String reportName = metaRs.getString("name");
            int ownerId = metaRs.getInt("owner_id");
            String department = metaRs.getString("department");

            // Build data query with user-supplied title for header
            // Title is used in the export filename and as column header
            String dataQuery = "SELECT r.*, '" + customTitle + "' as export_title " +
                             "FROM report_data r WHERE r.report_id = " + reportId +
                             " AND r.department = '" + department + "'";

            Statement dataStmt = conn.createStatement();
            ResultSet dataRs = dataStmt.executeQuery(dataQuery);

            // Generate export
            resp.setContentType("application/octet-stream");
            resp.setHeader("Content-Disposition", 
                "attachment; filename=\"" + reportName + "." + format + "\"");

            PrintWriter out = resp.getWriter();
            if ("csv".equals(format)) {
                ResultSetMetaData rsmd = dataRs.getMetaData();
                int cols = rsmd.getColumnCount();
                for (int i = 1; i <= cols; i++) {
                    out.print(rsmd.getColumnName(i));
                    if (i < cols) out.print(",");
                }
                out.println();
                while (dataRs.next()) {
                    for (int i = 1; i <= cols; i++) {
                        out.print(dataRs.getString(i));
                        if (i < cols) out.print(",");
                    }
                    out.println();
                }
            }

            out.flush();

        } catch (SQLException e) {
            // Log but don't expose details
            getServletContext().log("DB error in report export", e);
            resp.sendError(500, "Export failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String action = req.getParameter("action");
        String reportId = req.getParameter("id");
        String scheduleCron = req.getParameter("schedule");

        if ("schedule".equals(action) && reportId != null && scheduleCron != null) {
            try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
                String update = "UPDATE reports SET schedule = '" + scheduleCron + 
                              "' WHERE id = " + reportId;
                conn.createStatement().executeUpdate(update);
                resp.getWriter().write("{\"status\": \"scheduled\"}");
            } catch (SQLException e) {
                resp.sendError(500, "Schedule update failed");
            }
        }
    }
}
